const r = await Promise.all([
  tools.exec_command({"cmd":"pwd; git status --short; git log -5 --oneline; rg --files -g 'AGENTS.md' -g 'README.md' -g 'SCRATCHPAD.md' -g 'consensus.md' -g 'auto-loop.sh' -g '.claude/**' | sed -n '1,240p'","workdir":"/workspace/project","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"find .claude -maxdepth 4 -type f -o -type l | sort | sed -n '1,300p'; find /workspace/project -maxdepth 3 -type d -name '*stuff*' -o -path '/workspace/project' -print 2>/dev/null | sed -n '1,200p'; find /workspace/project -maxdepth 3 -type d -name 'skills_stuff' -print 2>/dev/null | sed -n '1,100p'","workdir":"/workspace/project","yield_time_ms":10000,"max_output_tokens":30000}),
  tools.exec_command({"cmd":"for f in AGENTS.md README.md .agents/overview.md .agents/docs-map.md; do [ -f \"$f\" ] && { echo \"--- $f\"; sed -n '1,260p' \"$f\"; }; done","workdir":"/workspace/project","yield_time_ms":10000,"max_output_tokens":40000})
]);
text(r.map(x=>x.output).join("\n\n---NEXT---\n\n"));

const r = await Promise.all([
  tools.exec_command({"cmd":"find /workspace/project -maxdepth 3 -mindepth 1 -type d -print | sort | sed -n '1,240p'; find /workspace/project -maxdepth 2 -type f \\( -name README.md -o -name AGENTS.md -o -name .gitignore \\) -print | sort | sed -n '1,160p'","workdir":"/workspace/project","yield_time_ms":10000,"max_output_tokens":20000}),
  tools.exec_command({"cmd":"if [ -d /workspace/project ]; then git -C /workspace/project status --short; git -C /workspace/project log -3 --oneline; fi; rg -n --glob 'README.md' --glob 'AGENTS.md' -i 'canonical|symlink|shared|persona|auto.company' /workspace/project 2>/dev/null | sed -n '1,240p'","workdir":"/workspace/project","yield_time_ms":10000,"max_output_tokens":20000})
]);
text(r.map(x=>x.output).join("\n\n---NEXT---\n\n"));
